import type { AttributeKey } from "@/lib/rules";

export interface ClanTrait {
  nivel: number;
  nome: string;
  resumo: string;
}

/** Talento de Clã (feat opcional, pego nos marcos de ASI — níveis 4/8/12/16/19). */
export interface ClanTalent {
  nome: string;
  preRequisito: string;
  resumo: string;
}

/**
 * Catálogo de Clãs — os 45 clãs jogáveis listados no índice do livro
 * "Estudos da Tsunade" (mais "Sem Clã"), lidos em detalhe página a página.
 * Cada um traz o bônus de atributo oficial e as Características de Clã por
 * nível (1/3/7/11/15/18) num resumo mecânico curto. A lista completa de
 * Jutsu exclusivos de cada clã ainda não foi catalogada (fica para quando o
 * catálogo de Jutsu for construído, Fase 4); os Talentos de Clã (`talentos`)
 * são preenchidos sob demanda, conforme lidos em detalhe — a maioria dos
 * clãs ainda tem esse campo vazio. `bonusCompleto: false` sinaliza um clã
 * cujo bônus de atributo de clã não foi localizado no texto-fonte (ex:
 * Senju, cujos bônus conhecidos vêm só de Talentos de Legado, não do clã
 * base).
 */
export interface ClanDefinition {
  key: string;
  nome: string;
  atributos: Partial<Record<AttributeKey, number>>;
  atributoEscolha?: string;
  resumo: string;
  bonusCompleto: boolean;
  tracos: ClanTrait[];
  talentos: ClanTalent[];
}

